import{_ as a,o as t,c as r,a0 as i}from"./chunks/framework.DJ-9CPBN.js";const p=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"overview.md","filePath":"overview.md"}'),o={name:"overview.md"};function n(s,e,l,d,h,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><h2 id="what-is-auditerra" tabindex="-1">What is Auditerra? <a class="header-anchor" href="#what-is-auditerra" aria-label="Permalink to &quot;What is Auditerra?&quot;">​</a></h2><p>Auditerra is a soil diagnostics and restoration platform that connects smallholder farmers in Kenya with agricultural experts through a low-connectivity digital network. The platform enables farmers to report land degradation issues using basic feature phones, allows experts to collect and verify field data offline, and gives institutional supervisors the tools to monitor restoration progress with verifiable, audit-ready evidence.</p><p>The platform transforms fragmented field observations into actionable restoration plans delivered directly to farmers via SMS, replacing unreliable satellite data with human-verified field measurements.</p><hr><h2 id="the-problem-we-solve" tabindex="-1">The Problem We Solve <a class="header-anchor" href="#the-problem-we-solve" aria-label="Permalink to &quot;The Problem We Solve&quot;">​</a></h2><h3 id="the-ground-truth-gap" tabindex="-1">The Ground-Truth Gap <a class="header-anchor" href="#the-ground-truth-gap" aria-label="Permalink to &quot;The Ground-Truth Gap&quot;">​</a></h3><p>Sub-Saharan Africa faces a severe ecological crisis. Current monitoring relies on satellite data that cannot verify subsurface soil health or localized realities. This creates a ground-truth gap that prevents effective restoration and blocks climate funding.</p><table tabindex="0"><thead><tr><th>Indicator</th><th>Scale</th></tr></thead><tbody><tr><td>Arable land actively degraded</td><td>65%</td></tr><tr><td>Productive land lost annually</td><td>12 million hectares</td></tr><tr><td>Fertile soil lost yearly</td><td>75 billion tons</td></tr></tbody></table><p>Satellite data cannot measure:</p><ul><li>Subsurface soil health (pH, nitrogen, phosphorus, potassium)</li><li>Localized socio-economic conditions</li><li>Actual on-the-ground restoration progress</li></ul><hr><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="offline-first-design" tabindex="-1">Offline-First Design <a class="header-anchor" href="#offline-first-design" aria-label="Permalink to &quot;Offline-First Design&quot;">​</a></h3><p>Field experts often work in areas with unreliable or no internet connectivity. The system is designed to function offline, storing data locally in IndexedDB and synchronizing automatically when connectivity is restored. This ensures that work continues uninterrupted regardless of network conditions.</p><h3 id="human-verified-data" tabindex="-1">Human-Verified Data <a class="header-anchor" href="#human-verified-data" aria-label="Permalink to &quot;Human-Verified Data&quot;">​</a></h3><p>Unlike satellite-based monitoring, Auditerra relies on on-the-ground verification. Every data point is collected by a trained expert who physically visits the farm. The security handshake system ensures that experts are actually present at the reported location, preventing fraud.</p><h3 id="audit-ready-workflow" tabindex="-1">Audit-Ready Workflow <a class="header-anchor" href="#audit-ready-workflow" aria-label="Permalink to &quot;Audit-Ready Workflow&quot;">​</a></h3><p>All actions in the system are tracked and auditable. The 60-day audit loop enforces re-testing to measure biological survival rather than just planting speed. This creates a verifiable impact record that can be presented to funders and stakeholders.</p><h3 id="role-based-access" tabindex="-1">Role-Based Access <a class="header-anchor" href="#role-based-access" aria-label="Permalink to &quot;Role-Based Access&quot;">​</a></h3><p>The system serves three distinct user personas with different needs and permissions:</p><ul><li><strong>Farmers</strong> report issues via USSD</li><li><strong>Experts</strong> collect diagnostic data and receive assignments</li><li><strong>Supervisors</strong> monitor progress and manage operations</li></ul><p>Each role has specific access controls and interfaces tailored to their workflow.</p><hr><h2 id="quick-links" tabindex="-1">Quick Links <a class="header-anchor" href="#quick-links" aria-label="Permalink to &quot;Quick Links&quot;">​</a></h2><ul><li><a href="/Auditerra-Technical-Documentation-/architecture/overview.html">Architecture</a> — System design and components</li><li><a href="/Auditerra-Technical-Documentation-/api/overview.html">Backend API</a> — Explore the endpoints</li><li><a href="/Auditerra-Technical-Documentation-/deployment/overview.html">Deployment</a> — Production setup</li></ul><hr><p><em>Built for Kenya&#39;s land restoration</em></p>',28)])])}const f=a(o,[["render",n]]);export{p as __pageData,f as default};
